function validate([root, to_delete]) {
  if (!Array.isArray(root)) return 'root is a level-order list of values.';
  if (root.length && root[0] === null) return 'Write an empty tree as [].';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < 1 || v > 1000))) return 'Node values are whole numbers from 1 to 1000.';
  let slots = 1, used = 0, nodes = 0;
  for (const v of root) {
    if (used >= slots) return 'The level-order list has values with no parent.';
    used++;
    if (v !== null) { nodes++; slots += 2; }
  }
  if (nodes > 1000) return 'The tree has at most 1000 nodes.';
  const present = root.filter(v => v !== null);
  if (new Set(present).size !== present.length) return 'Node values must be distinct.';
  if (!Array.isArray(to_delete) || to_delete.length > 1000) return 'to_delete has at most 1000 values.';
  if (to_delete.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'to_delete values are whole numbers from 1 to 1000.';
  if (new Set(to_delete).size !== to_delete.length) return 'to_delete values must be distinct.';
  return null;
}

