function delNodes(root, to_delete) {
  // Record each node's parent, then copy every surviving tree from its top.
  const parentOf = new Map();
  const nodes = [];
  const queue = root ? [root] : [];
  parentOf.set(root, null);
  while (queue.length) {
    const node = queue.shift();
    nodes.push(node);
    for (const child of [node.left, node.right]) {
      if (child) { parentOf.set(child, node); queue.push(child); }
    }
  }
  const gone = node => to_delete.includes(node.val);
  const copy = node => {
    if (!node || gone(node)) return null;
    return new TreeNode(node.val, copy(node.left), copy(node.right));
  };
  const result = [];
  for (const node of nodes) {
    const parent = parentOf.get(node);
    if (!gone(node) && (parent === null || gone(parent))) result.push(copy(node));
  }
  return result;
}

