function generate(rand, size) {
  const large = size === 'large';
  const count = large ? 700 + Math.floor(rand() * 301) : Math.floor(rand() * 9);
  const limit = large ? 1000 : 15;
  const pool = Array.from({ length: limit }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const values = pool.slice(0, count);
  // Grow a random shape: each new node takes a free child slot; deep trees prefer the newest slots.
  const deep = rand() < 0.3;
  const nodes = [];
  const free = [];
  for (const val of values) {
    const node = { val, left: null, right: null };
    if (free.length) {
      const pick = deep ? free.length - 1 - Math.floor(rand() * Math.min(3, free.length)) : Math.floor(rand() * free.length);
      const [owner, side] = free[pick];
      free.splice(pick, 1);
      owner[side] = node;
    }
    nodes.push(node);
    free.push([node, 'left'], [node, 'right']);
  }
  const tree = [];
  const queue = nodes.length ? [nodes[0]] : [];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) { tree.push(null); continue; }
    tree.push(node.val);
    queue.push(node.left, node.right);
  }
  while (tree.length && tree[tree.length - 1] === null) tree.pop();
  // Delete some present values, plus a few that are not in the tree.
  const share = rand();
  const to_delete = values.filter(() => rand() < share * 0.6);
  for (const val of pool.slice(count)) if (rand() < 0.1 && to_delete.length < 1000) to_delete.push(val);
  for (let i = to_delete.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [to_delete[i], to_delete[j]] = [to_delete[j], to_delete[i]];
  }
  return [tree, to_delete];
}
